            temp_result += operand[i + 1]
        elif operator[i] == "-":
            temp_result -= operand[i + 1]
        elif operator[i] == "*":
            temp_result *= operand[i + 1]
        elif operator[i] == "//":
            temp_result //= operand[i + 1]
        elif operator[i] == "**":
            temp_result **= operand[i + 1]
